		"* a\n+ b\n- c\n":     "<ul>\n<li>a</li>\n<li>b</li>\n<li>c</li>\n</ul>\n",
		"1. a\n2. b\n":        "<ol>\n<li>a</li>\n<li>b</li>\n</ol>\n",
